Object.assign(actions,{'practice-mode':setPracticeMode,practiceMode:setPracticeMode});
document.addEventListener('click',e=>{const link=e.target.closest('[data-nav]');if(link&&link.getAttribute('href')===location.hash){e.preventDefault();route();return;}const el=e.target.closest('[data-action]');if(el&&!el.disabled){const fn=actions[el.dataset.action];if(fn)fn(el.dataset.id);}});
document.addEventListener('submit',e=>{if(e.target.id==='answer-form'){e.preventDefault();actions['answer-check']();}else if(e.target.id==='booking-form'){e.preventDefault();bookingSubmit();}});
document.addEventListener('input',e=>{if(e.target.matches?.('[data-practice-delay]')&&Number.isInteger(Number(e.target.value))&&Number(e.target.value)>=1&&Number(e.target.value)<=30)setPracticeDelay(e.target.value);});
document.addEventListener('change',e=>{if(e.target.matches?.('[data-practice-delay]')){setPracticeDelay(e.target.value);return;}if(e.target.id==='journey-pet'){p.pet=['cat','dog','rabbit','mouse','hamster','fox','bear','panda','koala','tiger','lion','wolf','monkey','pig','cow','sheep','horse','unicorn','deer','giraffe','elephant','zebra','hippo','rhino','camel','kangaroo','sloth','otter','hedgehog','squirrel','raccoon','snake','turtle','frog','crocodile','penguin','owl','duck','swan','peacock','chick','fish','dolphin','whale','octopus','crab','butterfly','bee','ladybug','dragon'].includes(e.target.value)?e.target.value:'cat';save();header();}if(e.target.id==='profile-goal'||e.target.id==='daily-goal-select'){p.goal=Number(e.target.value);save();mapChapter=Math.ceil(currentLevel()/100);mapPage=Math.floor(((currentLevel()-1)%100)/20);route();}if(e.target.id==='chapter-select'){mapChapter=Number(e.target.value);mapPage=0;renderMap();}if(e.target.id==='daily-goal'){p.dailyGoal=Number(e.target.value);save();renderMap();}if(e.target.id==='word-filter'){wordFilter=e.target.value;wordPage=0;renderWords();}if(e.target.id==='import-file'){importFile(e.target.files[0]);e.target.value='';}});
document.addEventListener('keydown',e=>{if(e.repeat&&session?.phase==='quiz'&&e.key==='Enter'){e.preventDefault();return;}if(e.repeat&&session?.phase==='quiz'&&/^[1-4]$/.test(e.key))return;if(e.target.id==='word-search'&&e.key==='Enter'){actions.search();return;}if(!session||session.phase!=='quiz'||e.target.tagName==='INPUT'||e.target.closest?.('button,a,summary,select,textarea,[contenteditable]'))return;const q=session.queue[session.index];if(session.answered&&e.key==='Enter'){e.preventDefault();actions.next();}else if(q.options&&/^[1-4]$/.test(e.key)&&!session.answered){const option=q.options[Number(e.key)-1];if(option)answer(String(option.id));}});
window.addEventListener('hashchange',route);
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{const candidate=JSON.parse(e.newValue);if(C.validate(candidate)){p=typeof progressMerge==='function'?progressMerge(p,candidate):candidate;if(candidate.pet)p.pet=candidate.pet;if(candidate.goal)p.goal=candidate.goal;p.dailyGoal=candidate.dailyGoal;const merged=JSON.stringify(p);if(merged!==e.newValue){try{localStorage.setItem(KEY,merged);if(typeof progressSchedule==='function')progressSchedule();}catch{storageOK=false;}}if(typeof progressRefreshView==='function')progressRefreshView();else if(!session&&!(typeof basicsBusy==='function'&&basicsBusy()))route();else header();}}catch{}}});
window.addEventListener('storage',e=>{if(e.key!==PRACTICE_MODE_KEY&&e.key!==PRACTICE_DELAY_KEY)return;practiceAutoCancel();if(e.key===PRACTICE_MODE_KEY)practiceSpeed=PRACTICE_MODES.includes(e.newValue)?e.newValue:'slow';else{const seconds=Number(e.newValue);practiceDelaySeconds=Number.isInteger(seconds)&&seconds>=1&&seconds<=30?seconds:3;}refreshPracticeMode();});
async function init(){try{const raw=localStorage.getItem(KEY);if(raw){const candidate=JSON.parse(raw);if(C.validate(candidate))p=candidate;else toast('原有进度格式无法读取，请保留旧备份。');}}catch{storageOK=false;toast('进度读取失败，可以继续练习并导出备份。');}try{[words,missions,industries,examples,industryExtras]=await Promise.all([fetch('/data/words.json?v=9').then(r=>{if(!r.ok)throw Error();return r.json();}),fetch('/data/scenarios.json?v=2').then(r=>{if(!r.ok)throw Error();return r.json();}),fetch('/data/industries.json?v=12').then(r=>{if(!r.ok)throw Error();return r.json();}),fetch('/data/examples.json?v=8').then(r=>r.ok?r.json():{}),fetch('/data/industry_words.json?v=4').then(r=>{if(!r.ok)throw Error();return r.json();})]);if(words.length!==20000||missions.length!==12||industries.length!==17)throw Error();all=new Map([...words,...industryExtras,...missions.flatMap(m=>m.items)].map(w=>[String(w.id),w]));restoreIndustrySelection();loaded=true;mapChapter=Math.ceil(currentLevel()/100);mapPage=Math.floor(((currentLevel()-1)%100)/20);route();if(typeof progressStart==='function')progressStart();fetch('/api/membership').catch(()=>{});setInterval(()=>{if(p.friendName)friendSync(session&&(session.phase==='quiz'||session.phase==='study')?'studying':'idle').catch(()=>{});},30000);const challenge=Number(new URLSearchParams(location.search).get('challenge'));if(challenge>0&&challenge<=2000)toast(`朋友邀请你挑战第 ${challenge} 关。先从自己的进度出发。`);}catch{app.innerHTML='<section class="panel empty"><h1>词库还没加载成功。</h1><p>检查一下网络，然后重新打开页面。</p><button class="primary" onclick="location.reload()">重新加载</button></section>';}}
init();

let industryResumePending=false;
actions['industry-resume']=()=>{if(!industryPractice)return;chatReturnToPractice=false;industryResumePending=true;go('industries');};

document.addEventListener('click',e=>{const goalButton=e.target.closest('[data-goal]');if(!goalButton)return;const goal=Number(goalButton.dataset.goal);if(![5000,10000,20000].includes(goal)||goal===C.goal(p))return;p.goal=goal;save();mapChapter=Math.ceil(currentLevel()/100);mapPage=Math.floor(((currentLevel()-1)%100)/20);route();});

document.getElementById('pet-open').addEventListener('click',()=>{const select=document.getElementById('journey-pet'),dialog=document.getElementById('pet-dialog');document.getElementById('pet-grid').innerHTML=[...select.options].map(o=>`<button type="button" data-pet="${o.value}" class="${o.value===select.value?'selected':''}" aria-pressed="${o.value===select.value}">${esc(o.textContent)}</button>`).join('');dialog.showModal();});
document.getElementById('pet-close').addEventListener('click',()=>document.getElementById('pet-dialog').close());
document.getElementById('pet-grid').addEventListener('click',e=>{const choice=e.target.closest('[data-pet]');if(!choice)return;const select=document.getElementById('journey-pet');select.value=choice.dataset.pet;select.dispatchEvent(new Event('change',{bubbles:true}));document.getElementById('pet-dialog').close();document.getElementById('pet-open').focus();});
